50	  const tag = Buffer.from(tagB64, 'base64');
51	  const data = Buffer.from(dataB64, 'base64');
52	  const decipher = crypto.createDecipheriv('aes-256-gcm', key, iv);
53	  decipher.setAuthTag(tag);
